public java.util.List<java.util.List<Integer>> permute(int[] nums) {
    java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
    if (nums == null) {
        return res;
    }
    int n = nums.length;
    if (n == 0) {
        res.add(new java.util.ArrayList<>());
        return res;
    }
    int[] arr = nums.clone();
    java.util.Arrays.sort(arr);
    do {
        java.util.List<Integer> perm = new java.util.ArrayList<>(n);
        for (int num : arr) {
            perm.add(num);
        }
        res.add(perm);
    } while (nextPermutation(arr));
    return res;
}

private boolean nextPermutation(int[] arr) {
    int i = arr.length - 1;
    while (i > 0 && arr[i - 1] >= arr[i]) {
        i--;
    }
    if (i == 0) {
        return false;
    }
    int j = arr.length - 1;
    while (arr[i - 1] >= arr[j]) {
        j--;
    }
    int temp = arr[i - 1];
    arr[i - 1] = arr[j];
    arr[j] = temp;
    int l = i, r = arr.length - 1;
    while (l < r) {
        int t = arr[l];
        arr[l] = arr[r];
        arr[r] = t;
        l++;
        r--;
    }
    return true;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Determine the shortest string length to bound the search space.
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0; // Treat null string as invalid.
        }
        if (s.length() < minLen) {
            minLen = s.length();
        }
    }
    String first = strings.get(0);
    // Search for each possible length from longest to shortest.
    for (int L = minLen; L >= 1; L--) {
        java.util.Set<String> candidates = new java.util.HashSet<>();
        for (int i = 0; i <= first.length() - L; i++) {
            candidates.add(first.substring(i, i + L));
        }
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean matchesAll = true;
            for (int idx = 1; idx < strings.size(); idx++) {
                String t = strings.get(idx);
                if (!t.contains(cand) && !t.contains(rev)) {
                    matchesAll = false;
                    break;
                }
            }
            if (matchesAll) {
                return L;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;

    // 8 possible directions (horizontal, vertical, diagonal)
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    // Stack for iterative DFS
    int maxSize = rows * cols;
    int[] stackR = new int[maxSize];
    int[] stackC = new int[maxSize];

    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) {
            continue;
        }
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                int top = -1;
                // Push starting cell
                top++;
                stackR[top] = r;
                stackC[top] = c;
                visited[r][c] = true;

                while (top >= 0) {
                    int curR = stackR[top];
                    int curC = stackC[top];
                    top--; // pop

                    for (int d = 0; d < 8; d++) {
                        int nr = curR + dr[d];
                        int nc = curC + dc[d];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                            grid[nr][nc] == '@' && !visited[nr][nc]) {
                            top++;
                            stackR[top] = nr;
                            stackC[top] = nc;
                            visited[nr][nc] = true;
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

