public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int count = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        int num = entry.getKey();
        int freqNum = entry.getValue();
        if (num % 2 != 0) {
            continue;
        }
        int half = num / 2;
        Integer freqHalf = freq.get(half);
        if (freqHalf == null) {
            continue;
        }
        if (half == num) {
            if (freqHalf > 1) {
                count += freqNum;
            }
        } else {
            count += freqNum;
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0) throw new IllegalArgumentException("Dimension must be positive");
    if (start == null || end == null || paths == null) throw new IllegalArgumentException("Input cannot be null");
    if (start.length != n || end.length != n) throw new IllegalArgumentException("Start or end coordinates have incorrect length");
    if (java.util.Arrays.equals(start, end)) return "can be travelled";

    String startKey = java.util.stream.IntStream.of(start).mapToObj(Integer::toString).reduce((a, b) -> a + "," + b).orElse("");
    String endKey = java.util.stream.IntStream.of(end).mapToObj(Integer::toString).reduce((a, b) -> a + "," + b).orElse("");

    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

    for (int[] edge : paths) {
        if (edge == null || edge.length != 2 * n) {
            throw new IllegalArgumentException("Each path must contain exactly 2*n coordinates");
        }
        StringBuilder sb1 = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb1.append(edge[i]).append(',');
        }
        String key1 = sb1.toString();

        StringBuilder sb2 = new StringBuilder();
        for (int i = n; i < 2 * n; i++) {
            sb2.append(edge[i]).append(',');
        }
        String key2 = sb2.toString();

        graph.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
        graph.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
    }

    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String curr = queue.poll();
        if (curr.equals(endKey)) {
            return "can be travelled";
        }
        for (String neighbor : graph.getOrDefault(curr, java.util.Collections.emptyList())) {
            if (visited.add(neighbor)) {
                queue.add(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
