    return count == 0 ? 0.0 : (double) sum / count;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null) return false;
    int n = arr.length;
    if (n % 2 != 0) return false;
    if (k == 0) return false; // division by zero not allowed

    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq.put(r, freq.getOrDefault(r, 0) + 1);
    }

    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        int r = entry.getKey();
        int cnt = entry.getValue();
        int complement = (k - r) % k;
        if (r == complement) {
            if (cnt % 2 != 0) return false;
        } else {
            int compCnt = freq.getOrDefault(complement, 0);
            if (cnt != compCnt) return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    for (int[] e : edges) {
        adj[e[0]].add(e[1]);
        adj[e[1]].add(e[0]);
    }
    int[] res = new int[1];
    dfs(0, -1, adj, hasApple, res);
    return res[0];
}

private boolean dfs(int node, int parent, List<Integer>[] adj, boolean[] hasApple, int[] res) {
    boolean has = hasApple[node];
    for (int neighbor : adj[node]) {
        if (neighbor == parent) continue;
        boolean childHas = dfs(neighbor, node, adj, hasApple, res);
        if (childHas) {
            res[0] += 2; // go to child and back
            has = true;
        }
    }
    return has;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    char[] arr = s.toCharArray();
    java.util.Arrays.sort(arr);
    StringBuilder sb = new StringBuilder(arr.length);
    int start = 0;
    int end = arr.length - 1;
    while (start <= end) {
        // Ascending pass
        while (start <= end) {
            sb.append(arr[start]);
            start++;
        }
        // Descending pass
        while (start <= end) {
            sb.append(arr[end]);
            end--;
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int total = 0;
    for (int v : nums) {
        total += v;
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((total * k) % n != 0) {
            continue;
        }
        int target = (total * k) / n;
        if (hasSubsetOfSizeWithSum(nums, k, target)) {
            return true;
        }
    }
    return false;
}

private boolean hasSubsetOfSizeWithSum(int[] nums, int k, int target) {
    int n = nums.length;
    int leftSize = n / 2;
    int rightSize = n - leftSize;

    java.util.List<java.util.List<Integer>> leftSums = new java.util.ArrayList<>(leftSize + 1);
    java.util.List<java.util.List<Integer>> rightSums = new java.util.ArrayList<>(rightSize + 1);
    for (int i = 0; i <= leftSize; i++) {
        leftSums.add(new java.util.ArrayList<>());
    }
    for (int i = 0; i <= rightSize; i++) {
        rightSums.add(new java.util.ArrayList<>());
    }

    // Generate sums for the left half
    for (int mask = 0; mask < (1 << leftSize); mask++) {
        int sum = 0;
        int count = 0;
        for (int i = 0; i < leftSize; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[i];
                count++;
            }
        }
        leftSums.get(count).add(sum);
    }

    // Generate sums for the right half
    for (int mask = 0; mask < (1 << rightSize); mask++) {
        int sum = 0;
        int count = 0;
        for (int i = 0; i < rightSize; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[leftSize + i];
                count++;
            }
        }
        rightSums.get(count).add(sum);
    }

    // Convert right sums to sets for faster lookup
    java.util.List<java.util.HashSet<Integer>> rightSets = new java.util.ArrayList<>(rightSize + 1);
    for (int i = 0; i <= rightSize; i++) {
        rightSets.add(new java.util.HashSet<>(rightSums.get(i)));
    }

    // Check combinations of subsets from left and right halves
    for (int leftCount = 0; leftCount <= leftSize; leftCount++) {
        int rightCount = k - leftCount;
        if (rightCount < 0 || rightCount > rightSize) {
            continue;
        }
        java.util.List<Integer> leftList = leftSums.get(leftCount);
        java.util.HashSet<Integer> rightSet = rightSets.get(rightCount);
        for (int leftSum : leftList) {
            if (rightSet.contains(target - leftSum)) {
                return true;
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // You can start at step 0 or step 1 (top). Minimum cost is 0.
        return 0;
    }
    // dp[i] represents the minimum cost to reach step i.
    // We only need the last two values.
    int prevPrev = 0; // cost to reach step 0
    int prev = 0;     // cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int costFromPrevPrev = prevPrev + cost[i - 2];
        int costFromPrev = prev + cost[i - 1];
        int cur = Math.min(costFromPrevPrev, costFromPrev);
        prevPrev = prev;
        prev = cur;
    }
    return prev;
}

public int uniqueMorseRepresentations(String[] words) {
    try {
        if (words == null) {
            return 0;
        }
        String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",".---",
                          "-.-",".-..","--","-.","---",".--.", "--.-",".-.","...","-",
                          "..-","...-",".--","-..-","-.--","--.."};
        Set<String> transformations = new HashSet<>();
        for (String word : words) {
            if (word == null) {
                word = "";
            }
            StringBuilder sb = new StringBuilder();
            for (char ch : word.toCharArray()) {
                if (ch >= 'a' && ch <= 'z') {
                    sb.append(morse[ch - 'a']);
                } else if (ch >= 'A' && ch <= 'Z') {
                    sb.append(morse[ch - 'A']);
                } else {
                    // non-alphabetic characters are ignored in Morse translation
                }
            }
            transformations.add(sb.toString());
        }
        return transformations.size();
    } catch (Exception e) {
        // In case of any unexpected runtime issues, return 0 as a graceful fallback
        return 0;
    }
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) return false;
    int n = s.length();
    if (n < k) return false;
    // For practical limits, if k is too large it's impossible for s to contain all codes
    if (k >= 20) return false; // 2^20 > 1,000,000 – unlikely with typical s length
    int total = 1 << k;
    java.util.HashSet<Integer> seen = new java.util.HashSet<>(total);
    int mask = 0;
    int maskLimit = total - 1;
    for (int i = 0; i < n; i++) {
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen.add(mask);
            if (seen.size() == total) return true;
        }
    }
    return seen.size() == total;
}

