public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int insertions = 0;
    int balance = 0; // number of unmatched '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--;
            } else {
                // Need an opening bracket before this ')'
                insertions++;
            }
        } else {
            // Invalid character: ignore or throw
            // For safety, treat as no-op
        }
    }
    // Add closing brackets for any unmatched '('
    insertions += balance;
    return insertions;
}

