    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    java.util.Set<java.lang.String> used = new java.util.HashSet<>();
    int[] max = {0};
    backtrack(s, 0, used, 0, max);
    return max[0];
}

private void backtrack(String s, int pos, java.util.Set<java.lang.String> used, int count, int[] max) {
    if (pos == s.length()) {
        if (count > max[0]) {
            max[0] = count;
        }
        return;
    }
    for (int i = pos + 1; i <= s.length(); i++) {
        java.lang.String sub = s.substring(pos, i);
        if (used.contains(sub)) {
            continue;
        }
        used.add(sub);
        backtrack(s, i, used, count + 1, max);
        used.remove(sub);
    }
}

public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if (log.equals("../")) {
            if (depth > 0) {
                depth--;
            }
        } else if (log.equals("./")) {
            // stay in current folder, no change
            continue;
        } else {
            // directory name ending with '/'
            if (!log.isEmpty() && log.charAt(log.length() - 1) == '/') {
                depth++;
            }
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("String length must be positive.");
    }
    int minPossible = n;          // all 'a's
    int maxPossible = 26 * n;     // all 'z's
    if (k < minPossible || k > maxPossible) {
        throw new IllegalArgumentException("k must be between " + minPossible + " and " + maxPossible + ".");
    }
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a');
    int delta = k - n; // how much to add beyond all 'a's
    for (int i = n - 1; i >= 0 && delta > 0; i--) {
        int inc = Math.min(delta, 25); // maximum increment per position
        result[i] = (char) ('a' + inc);
        delta -= inc;
    }
    return new String(result);
}

public static double calculateProbability(int n) {
    // According to the classic airplane seating problem, the probability that
    // the last passenger gets his own seat is 1.0 for n = 1, and 0.5 for n > 1.
    if (n <= 1) {
        return 1.0;
    }
    return 0.5;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        // If the array is null or empty, there is no unique element.
        // Returning 0 as a neutral value; alternatively, could throw an exception.
        return 0;
    }
    long result = 0L;
    for (int i = 0; i < 32; i++) {
        int bitCount = 0;
        for (int num : nums) {
            bitCount += (num >> i) & 1;
        }
        bitCount %= 3;
        if (bitCount != 0) {
            result |= ((long) bitCount << i);
        }
    }
    return (int) result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long total = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            total += higher * factor;
        } else if (cur == 1) {
            total += higher * factor + lower + 1;
        } else {
            total += (higher + 1) * factor;
        }
    }
    return (int) total;
}

public static boolean isPowerOfTwo(int n) {
    // A number is a positive power of two if it is greater than 0 and has only one bit set.
    if (n <= 0) {
        return false;
    }
    // Using bitwise trick: powers of two have the property n & (n-1) == 0
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        int temp = num;
        while (temp > 0) {
            sum += temp % 10;
            temp /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    // dp[i][j][k] where k: 0=horizontal, 1=vertical, 2=diagonal, 3=anti-diagonal
    int[][][] dp = new int[m][n][4];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1; // horizontal
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1; // vertical
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1; // diagonal
                dp[i][j][3] = (i > 0 && j + 1 < n ? dp[i - 1][j + 1][3] : 0) + 1; // anti-diagonal
                maxLen = Math.max(maxLen, Math.max(Math.max(dp[i][j][0], dp[i][j][1]),
                                                    Math.max(dp[i][j][2], dp[i][j][3])));
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) return "0";
    boolean negative = n < 0;
    long val = Math.abs((long) n); // use long to handle Integer.MIN_VALUE
    String numStr = String.valueOf(val);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.append(numStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }
    if (negative) sb.append('-');
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    // Precompute perfect squares up to 2 * max(A)
    int maxVal = A[n - 1];
    int maxSum = maxVal * 2;
    java.util.HashSet<Integer> squares = new java.util.HashSet<>();
    for (int k = 0; k * k <= maxSum; k++) {
        squares.add(k * k);
    }
    boolean[] visited = new boolean[n];
    java.util.concurrent.atomic.AtomicInteger count = new java.util.concurrent.atomic.AtomicInteger(0);

    java.util.function.Consumer<Void> dfs = new java.util.function.Consumer<Void>() {
        @Override
        public void accept(Void unused) {
            int depth = 0;
            for (int i = 0; i < n; i++) {
                if (visited[i]) continue;
                if (i > 0 && A[i] == A[i - 1] && !visited[i - 1]) continue;
                visited[i] = true;
                dfsRec(depth + 1, A[i]);
                visited[i] = false;
            }
        }

        private void dfsRec(int depth, int lastVal) {
            if (depth == n) {
                count.incrementAndGet();
                return;
            }
            for (int i = 0; i < n; i++) {
                if (visited[i]) continue;
                if (i > 0 && A[i] == A[i - 1] && !visited[i - 1]) continue;
                if (!squares.contains(lastVal + A[i])) continue;
                visited[i] = true;
                dfsRec(depth + 1, A[i]);
                visited[i] = false;
            }
        }
    };

    dfs.accept(null);
    return count.get();
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int maxArea = 0;
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    for (int i = 0; i <= n; i++) {
        int currHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && heights[stack[top]] > currHeight) {
            int h = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = h * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int idx = 0;
    for (int sum = 0; sum < rows + cols - 1; sum++) {
        int iStart = Math.max(0, sum - (cols - 1));
        int iEnd = Math.min(rows - 1, sum);
        if (sum % 2 == 0) {
            for (int i = iEnd; i >= iStart; i--) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        } else {
            for (int i = iStart; i <= iEnd; i++) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no higher permutation
    }
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // swap digits[i] and digits[j]
    char tmp = digits[i];
    digits[i] = digits[j];
    digits[j] = tmp;
    // reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    long result = 0;
    for (int k = 0; k < len; k++) {
        result = result * 10 + (digits[k] - '0');
        if (result > Integer.MAX_VALUE) {
            return -1; // result would overflow int
        }
    }
    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }
    return build(n, n);
}

private static List<String> build(int len, int totalLen) {
    if (len == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (len == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }
    List<String> middle = build(len - 2, totalLen);
    List<String> res = new ArrayList<>();
    for (String s : middle) {
        if (len != totalLen) {
            res.add("0" + s + "0");
        }
        res.add("1" + s + "1");
        res.add("6" + s + "9");
        res.add("8" + s + "8");
        res.add("9" + s + "6");
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Compute cross product of vectors (p2 - p1) and (p3 - p1)
    int cross = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int next = Math.min(next2, Math.min(next3, next5));
        ugly[i] = next;
        if (next == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (next == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (next == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
        }
    }
    if (current > max) {
        max = current;
    }
    return max;
}

public static java.util.List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, java.util.List<Integer> res) {
    if (current > n) {
        return;
    }
    res.add(current);
    for (int d = 0; d <= 9; d++) {
        long next = current * 10L + d;
        if (next > n) {
            break;
        }
        dfs((int) next, n, res);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // Initialize dp array with a large value
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    int n = s.length();
    while (i < n) {
        if (s.charAt(i) != ' ') {
            int start = i;
            while (i < n && s.charAt(i) != ' ') {
                i++;
            }
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
        } else {
            while (i < n && s.charAt(i) == ' ') {
                result.append(' ');
                i++;
            }
        }
    }
    return result.toString();
}
